package main

import (
    "encoding/json"
    "fmt"
)

type Config struct {
    Host string `json:"host"`
    Port int    `json:"port"`
}

func main() {
    data := []byte(`{"host":"localhost"}`)
    var c Config
    json.Unmarshal(data, &c)
    fmt.Println(c.Host, c.Port)
}
